/* ==========================================================================
   euroarmour3d.js -- BRITISH, FRENCH AND GERMAN ARMOUR

   WHY THIS FILE EXISTS. Resolve any gbr / fra / deu ground vehicle through
   render3d.js modelKeyFor() and the answer is always an American one. There
   are 147 of them in the roster and before this file the number with a model
   of their own was ZERO. Every Challenger, every Leopard, every Leclerc drew
   as mbt_n, the M1A2 SEP v3 in js/units3d.js:7310. Every Warrior, Marder,
   Puma and VBCI drew as ifv_n, the M2A3 Bradley. Every Challenger in the
   heavy role drew as hvy_n. The peer scan at render3d.js:311 is working as
   designed - it prefers an honest stand-in to the grey box of
   fallbackModel() - but "they borrow American hulls" was meant to describe
   the 1950s, when the Bundeswehr really did drive M47 Pattons and the French
   really did field M47s beside the AMX-13. It was never meant to describe a
   Leopard 2A7V.

   TWENTY-FIVE ids are claimed here, chosen on one test: would a player
   looking at the sprite see the WRONG VEHICLE, not merely a generic one?
   Three faults pass that test and everything in this file has at least one.

     1. THE TURRET IS THE WRONG SHAPE, on a tank whose turret is the single
        most recognisable thing about it. The Leopard 2A5's arrowhead wedge
        (1995) and the Challenger's flat-faced Chobham block are the two most
        photographed turret outlines in NATO, and both were drawing as the
        Abrams' long unwedged bustle.
     2. THE ARMAMENT IS THE WRONG KIND. A Bradley carries a two-tube TOW box
        bolted to the left cheek of its turret and at forty screen pixels
        that box is half the turret. A Warrior has no ATGM at all and a 30 mm
        RARDEN barrel so slender it is nearly a wire. A Puma's turret has no
        hatch, no cupola and nobody inside it whatsoever.
     3. IT IS RUNNING ON THE WRONG THING. The VBCI is a 32-tonne 8x8 and it
        was drawing on tracks. That is not a wrong detail, it is a wrong
        class of vehicle.

   WHAT IS DELIBERATELY NOT HERE. Conqueror, Centurion, Chieftain, Leopard 1,
   AMX-30, AMX-13, Saracen, FV432, Scorpion, Scimitar, Ajax, Saladin, AS-90,
   Abbot, Archer, CAESAR, Gepard, Luchs, Fennek, Wiesel, PzH 2000 and the
   rest still borrow. Several of them have earned a model - the CAESAR is a
   6x6 lorry drawing as a tracked M109 and the whole CVR(T) family is tracked
   and drawing as a wheeled Stryker MGS - but this file is the handful, not
   the sweep, and the handful is the four present-day flagships plus the era
   rows that share their hull.

   ON REGISTERING UNDER THE DEF ID. render3d.js getModel() computes
     K = (ERA_KIT[era] && key !== def.id) ? ERA_KIT[era] : null
   so the era repaint and the era bolt-on kit fire ONLY for a model that is a
   borrowed stand-in. From the moment these registrations land, ERA_KIT stops
   running on all twenty-five ids and the `base` / `tones` in each parameter
   object below is the FINAL paint. js/tel3d.js:2465 makes the same point for
   the ballistic launchers and js/sam3d.js does it for the era SAMs. So every
   row below carries a PERIOD palette rather than a family green, and the
   periods are real:
     RAL 6014 gelboliv, one flat colour, is Bundeswehr standard until 1984.
     The NATO three-tone - RAL 6031 bronze green under RAL 8027 leather brown
       and RAL 9021 tar black - replaces it from 1984 and is still current;
       the French Army adopts the same scheme in the 1990s.
     British BAOR armour of the same period is infrared-reflecting green
       over black, two colours only.
     Light Stone: Challenger 1 and Warrior in DESERT SABRE, February 1991,
       and Challenger 2 and Warrior in the Theatre Entry Standard fit from
       2007 in Iraq and Helmand.

   Model space is the house convention: +X forward, +Y left, +Z up, ground at
   z = 0, real metres throughout. A group named "turret" is slewed by
   entities.js; a group named "roadwheel" is spun by render3d.js:1080 about
   its LOCAL Y at the vehicle's real speed, which is why every wheel and
   sprocket below is a plain cylinder left on its default Y axis and is not
   rotated - rotating the group would make render3d spin it about a tilted
   axis and the wheel would wobble instead of turn.

   DIMENSIONS are from Jane's Armour and Artillery, the RBSL / KNDS Deutschland
   / Nexter / Rheinmetall data sheets and the UK MoD and Bundeswehr equipment
   pages. Barrel length follows from the calibre-length: a 120 mm L/44 is
   5.28 m of tube, an L/55 is 6.60 m, the GIAT CN120-26 is L/52 and so 6.24 m.
   Overall lengths below are GUN FORWARD, which is what the model measures.

   A NOTE ON SCALE, because it is a real limitation and not an oversight.
   render3d.js sizes a ground vehicle from def.r, not from the model - 
   targetLen = def.r * 2.1 * PXM * CFG.MODEL_SCALE - so every r:16 tank is
   drawn to the same screen length whatever its real length is. That is the
   existing convention ("ground: MBT ~ 1 tile") and mbt_n, mbt_p and mbt_c
   already share it despite differing by a metre in life. The consequence
   here is that a Challenger 2, being 11.50 m gun-forward against the
   Abrams' 9.83 m, is drawn about 15% smaller than it should be relative to
   an Abrams standing beside it. The proportions WITHIN each vehicle are
   real, which is what the eye actually reads at this zoom, so the real
   lengths are kept and the artefact is documented rather than hidden by
   shortening the guns.
   ========================================================================== */

if (typeof UNIT_MODELS === "undefined") { var UNIT_MODELS = {}; }

var EuroArmour3D = (function () {
  "use strict";

  /* ------------------------------------------------------------------ paint
     A seeded generator, not Math.random(). mbt_n uses Math.random() and every
     Abrams in a platoon therefore wears different blotches; that is fine for
     one hero model and wrong for a troop of four Leopards, which in a
     photograph are identical because they came out of the same paint shop. */
  function lcg(seed) {
    var s = (seed >>> 0) || 1;
    return function () { s = (s * 1664525 + 1013904223) >>> 0; return s / 4294967296; };
  }

  function camoTex(THREE, base, tones, seed, blobs) {
    var cv = document.createElement("canvas"); cv.width = 256; cv.height = 256;
    var p = cv.getContext("2d"), R = lcg(seed), i, j, x, y, gr;
    p.fillStyle = base; p.fillRect(0, 0, 256, 256);
    /* the disruptive pattern, painted as soft ellipses because a NATO scheme
       is sprayed freehand off a template and has no hard edge at two metres,
       let alone at this zoom. A row with tones:[] is single-colour and skips
       the loop entirely - which is exactly what gelboliv and Light Stone are. */
    tones = tones || [];
    for (j = 0; j < tones.length; j++) {
      p.fillStyle = tones[j];
      for (i = 0; i < (blobs || 5); i++) {
        x = R() * 256; y = R() * 256;
        p.beginPath();
        p.ellipse(x, y, 24 + R() * 44, 14 + R() * 26, R() * 3.1, 0, 6.2832);
        p.fill();
      }
    }
    /* weld seams and panel joins. Armour plate is welded, not pressed, and
       the seam is the only thing on a flat green flank that says so. */
    p.strokeStyle = "rgba(0,0,0,0.22)"; p.lineWidth = 1;
    for (i = 0; i < 5; i++) { y = 20 + R() * 216; p.beginPath(); p.moveTo(0, y); p.lineTo(256, y); p.stroke(); }
    for (i = 0; i < 7; i++) { x = 16 + R() * 224; p.beginPath(); p.moveTo(x, 0); p.lineTo(x, 256); p.stroke(); }
    /* exhaust soot and track-thrown mud, weighted to the lower half */
    for (i = 0; i < 9; i++) {
      x = R() * 256; y = 120 + R() * 136;
      gr = p.createRadialGradient(x, y, 2, x, y, 12 + R() * 22);
      gr.addColorStop(0, "rgba(22,19,12,0.16)"); gr.addColorStop(1, "rgba(22,19,12,0)");
      p.fillStyle = gr; p.fillRect(x - 36, y - 36, 72, 72);
    }
    for (i = 0; i < 20; i++) {
      p.fillStyle = "rgba(" + (R() < 0.5 ? "0,0,0" : "255,255,255") + "," + (0.025 + R() * 0.04).toFixed(3) + ")";
      p.fillRect(R() * 236, R() * 236, 16 + R() * 54, 10 + R() * 40);
    }
    var t = new THREE.CanvasTexture(cv);
    t.wrapS = t.wrapT = THREE.RepeatWrapping;
    return t;
  }

  /* ------------------------------------------------------------- primitives
     Axis discipline, because getting it wrong is silent: a CylinderGeometry
     is built about +Y. cyx rotates it to +X (gun tubes), czu rotates it to
     +Z (cupolas, antennas, hatch rings), and cyy leaves it alone (road
     wheels, sprockets, return rollers - anything that turns about the
     vehicle's cross axis and must stay on local Y for render3d to spin it). */
  function kit(THREE, P, C) {
    var K = {};
    K.hull = new THREE.MeshStandardMaterial({
      map: camoTex(THREE, P.base, P.tones, P.seed, P.blobs), metalness: 0.22, roughness: 0.68 });
    K.hull.map.repeat.set(2, 1);
    K.tur = new THREE.MeshStandardMaterial({
      map: camoTex(THREE, P.base, P.tones, P.seed + 7, P.blobs), metalness: 0.22, roughness: 0.68 });
    K.dark = new THREE.MeshStandardMaterial({ color: 0x23251f, metalness: 0.18, roughness: 0.92 });
    K.steel = new THREE.MeshStandardMaterial({ color: 0x55574a, metalness: 0.38, roughness: 0.54 });
    K.rub = new THREE.MeshStandardMaterial({ color: 0x191a17, metalness: 0.05, roughness: 0.96 });
    K.glass = new THREE.MeshPhysicalMaterial({ color: 0x18242c, metalness: 0.25, roughness: 0.15 });
    K.team = new THREE.MeshStandardMaterial({
      color: (C && C.team !== undefined) ? C.team : 0xcccccc, metalness: 0.2, roughness: 0.55 });
    return K;
  }
  function bx(THREE, parent, sx, sy, sz, px, py, pz, mat) {
    var m = new THREE.Mesh(new THREE.BoxGeometry(sx, sy, sz), mat);
    m.position.set(px, py, pz); parent.add(m); return m;
  }
  function cyx(THREE, parent, r, len, px, py, pz, mat, seg) {         /* axis +X */
    var m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, seg || 12), mat);
    m.rotation.z = Math.PI / 2; m.position.set(px, py, pz); parent.add(m); return m;
  }
  function czu(THREE, parent, r, len, px, py, pz, mat, seg) {         /* axis +Z */
    var m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, seg || 12), mat);
    m.rotation.x = Math.PI / 2; m.position.set(px, py, pz); parent.add(m); return m;
  }
  function cyy(THREE, parent, r, len, px, py, pz, mat, seg) {         /* axis +Y */
    var m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, seg || 14), mat);
    m.position.set(px, py, pz); parent.add(m); return m;
  }

  /* ---------------------------------------------------------- running gear
     Two track runs and never one slab: mbt_n's comment at js/units3d.js:7360
     records why, and the reason holds here. The lower run also puts the
     vehicle ON the ground - render3d.js only snaps a belly that has gone
     BELOW z = 0, so a hull whose lowest mesh sits at +0.10 hovers with its
     shadow detached from it. */
  function gear(THREE, g, K, o) {
    var s, i, wg, hg, sg;
    wg = new THREE.CylinderGeometry(o.r, o.r, o.tw * 0.78, 16);
    hg = new THREE.CylinderGeometry(o.r * 0.40, o.r * 0.40, o.tw * 0.86, 10);
    sg = new THREE.CylinderGeometry(o.sr, o.sr, o.tw * 0.72, 12);
    for (s = -1; s <= 1; s += 2) {
      bx(THREE, g, o.tl, o.tw, 0.11, o.tx, o.ty * s, 0.055, K.dark);
      bx(THREE, g, o.tl * 0.94, o.tw, 0.11, o.tx, o.ty * s, o.r * 2 + 0.06, K.dark);
      for (i = 0; i < o.n; i++) {
        var rw = new THREE.Group(); rw.name = "roadwheel";
        rw.position.set(o.x0 + i * o.dx, o.ty * s, o.r);
        rw.add(new THREE.Mesh(wg, K.rub));
        rw.add(new THREE.Mesh(hg, K.steel));
        /* the bolt ring is what makes the rotation read. A smooth cylinder
           turning about its own axis shows nothing at all. */
        for (var b = 0; b < 5; b++) {
          var a = b / 5 * Math.PI * 2 + 0.3;
          var bolt = new THREE.Mesh(
            new THREE.CylinderGeometry(o.r * 0.075, o.r * 0.075, o.tw * 0.90, 5), K.steel);
          bolt.position.set(Math.cos(a) * o.r * 0.60, 0, Math.sin(a) * o.r * 0.60);
          rw.add(bolt);
        }
        g.add(rw);
      }
      /* Sprocket and idler, and WHICH END the sprocket is on is a real tell
         that differs across this file: Leopard 2, Challenger and Leclerc all
         drive from the REAR and idle at the front; Warrior, Marder and Puma
         all drive from the FRONT. */
      for (var q = 0; q < 2; q++) {
        var drv = q === 0;
        var w2 = new THREE.Group(); w2.name = "roadwheel";
        w2.position.set(drv ? o.sx : o.ix, o.ty * s, o.sr + 0.04);
        w2.add(new THREE.Mesh(sg, K.steel));
        for (var t = 0; t < 8; t++) {
          var ta = t / 8 * Math.PI * 2;
          var th = new THREE.Mesh(new THREE.BoxGeometry(
            o.sr * (drv ? 0.30 : 0.22), o.tw * 0.66, o.sr * (drv ? 0.26 : 0.20)), K.dark);
          th.position.set(Math.cos(ta) * o.sr * 0.82, 0, Math.sin(ta) * o.sr * 0.82);
          th.rotation.y = -ta; w2.add(th);
        }
        g.add(w2);
      }
      /* return rollers: the track's upper run rides on them, and their number
         and spacing is one of the few ways to tell two green hulls apart from
         abeam. Leopard 2 has four a side, Challenger three, Marder three. */
      for (i = 0; o.rr && i < o.rr.length; i++)
        cyy(THREE, g, o.rrR || 0.11, o.tw * 0.70, o.rr[i], o.ty * s, o.r * 2 + 0.02, K.steel, 8);

      /* ---- skirts ---- */
      var sk = o.skirt, n, w, x;
      if (sk && sk.style === "panel") {
        /* separate hanging armour panels with visible vertical joins: the
           Warrior, Marder, Puma - and Abrams - pattern. */
        n = sk.segs || 6; w = (sk.x1 - sk.x0) / n;
        for (i = 0; i < n; i++)
          bx(THREE, g, w * 0.93, sk.t, sk.h, sk.x0 + w * (i + 0.5), sk.y * s, sk.z, K.hull);
        bx(THREE, g, sk.x1 - sk.x0 + 0.2, sk.t * 2.2, 0.06,
           (sk.x0 + sk.x1) / 2, (sk.y - 0.10) * s, sk.z + sk.h / 2, K.hull);
      } else if (sk && sk.style === "slab") {
        /* one continuous plate nose to tail, deep enough to hide the running
           gear almost completely. This is the Leclerc, and it is the fastest
           way to tell a Leclerc from anything else on the map: no other tank
           in the roster shows a blank wall down its flank. */
        bx(THREE, g, sk.x1 - sk.x0, sk.t, sk.h, (sk.x0 + sk.x1) / 2, sk.y * s, sk.z, K.hull);
        bx(THREE, g, sk.x1 - sk.x0, sk.t * 2.0, 0.07,
           (sk.x0 + sk.x1) / 2, (sk.y - 0.10) * s, sk.z + sk.h / 2, K.hull);
      } else if (sk && sk.style === "heavy") {
        /* Leopard 2: heavy hinged plates over the forward stations where a
           frontal hit is likely, thin rubber-and-steel flaps over the rest.
           The step between the two is in every side-on photograph of the
           type and it is the cheapest possible Leopard tell. */
        bx(THREE, g, sk.hx1 - sk.hx0, sk.t * 2.4, sk.h * 1.12,
           (sk.hx0 + sk.hx1) / 2, sk.y * s, sk.z, K.hull);
        n = sk.segs || 4; w = (sk.hx0 - sk.x0) / n;
        for (i = 0; i < n; i++)
          bx(THREE, g, w * 0.92, sk.t, sk.h * 0.90, sk.x0 + w * (i + 0.5), sk.y * s, sk.z, K.hull);
      }
      /* bar (slat) armour standing off the flank on posts. Challenger 2 TES
         and the Warrior TES fit carried it in Iraq and Helmand from 2007,
         and the Leclerc XLR carries cage under the SCORPION standard. */
      if (o.bar) {
        for (i = 0; i < 6; i++)
          bx(THREE, g, o.bar.x1 - o.bar.x0, 0.03, 0.02,
             (o.bar.x0 + o.bar.x1) / 2, o.bar.y * s, o.bar.z + i * 0.17, K.dark);
        for (i = -1; i <= 1; i += 2)
          bx(THREE, g, 0.04, 0.05, 0.95,
             (o.bar.x0 + o.bar.x1) / 2 + i * (o.bar.x1 - o.bar.x0) * 0.42,
             o.bar.y * s, o.bar.z + 0.42, K.dark);
      }
    }
  }

  /* ---- bank of smoke grenade dischargers, angled out and up ---- */
  function smoke(THREE, tur, K, o) {
    for (var s = -1; s <= 1; s += 2)
      for (var i = 0; i < o.n; i++) {
        var t = cyx(THREE, tur, 0.048, 0.26,
          o.x - i * 0.115, (o.y - i * 0.012) * s, o.z + i * 0.016, K.dark, 8);
        t.rotation.y = -0.35; t.rotation.x = s * 0.55;
      }
  }

  /* ---- the arrowhead. Leopard 2A5, 1995: two spaced plates bolted to the
     turret face in a V, adding roughly 0.65 m to the nose of the turret and
     changing the tank's outline more than any other NATO retrofit ever has.
     It is SPACED armour - there is an air gap behind it - so it is built as
     two plates standing proud of the mantlet and not as a fatter turret. */
  function wedge(THREE, tur, K, o) {
    for (var s = -1; s <= 1; s += 2) {
      var p = bx(THREE, tur, o.len, 0.16, o.h, o.x, o.y * s, o.z, K.tur);
      p.rotation.z = s * o.yaw;
      var e = bx(THREE, tur, o.len * 0.96, 0.05, 0.05, o.x, o.y * s, o.z + o.h / 2, K.dark);
      e.rotation.z = s * o.yaw;
    }
  }

  /* ================================================================ tracked
     One builder for eleven vehicles; everything that differs is in the
     parameter object. That is the tel3d.js pattern and it is used for the
     same reason - these shapes are genuinely related, and a second
     hand-written builder would drift away from the first within a month. */
  function buildTracked(P) {
    return function (THREE, M, C) {
      var g = new THREE.Group(), K = kit(THREE, P, C), i;

      /* ---- hull ---- */
      g.add(new THREE.Mesh(M.loft(THREE, P.hull, 12), K.hull));
      /* the glacis: a separate raked slab so the nose reads as ARMOUR and not
         as the end of a loft. Every vehicle here has one and the rake is its
         own - a Leopard 2's upper front plate lies flatter than a Warrior's. */
      if (P.glacis) {
        var gl = bx(THREE, g, P.glacis.len, P.glacis.w, 0.10, P.glacis.x, 0, P.glacis.z, K.hull);
        gl.rotation.y = P.glacis.rake;
      }
      /* driver's hatch and vision blocks. Centreline on a Challenger, right
         of centre on a Leopard 2, left on a Leclerc - it is free period and
         national detail and it costs four meshes. */
      if (P.driver) {
        czu(THREE, g, 0.30, 0.06, P.driver.x, P.driver.y, P.driver.z, K.hull, 12);
        for (i = -1; i <= 1; i++)
          bx(THREE, g, 0.07, 0.16, 0.07, P.driver.x + 0.16, P.driver.y + i * 0.22, P.driver.z + 0.05, K.glass);
      }
      /* engine deck louvres: the hottest, flattest, most obviously mechanical
         surface on an armoured vehicle, and on the IFVs they are at the NOSE
         because Warrior, Marder and Puma are all front-engined. */
      if (P.deck)
        for (i = 0; i < 5; i++)
          bx(THREE, g, 0.09, P.deck.w, 0.05, P.deck.x - i * 0.20, 0, P.deck.z, K.dark);
      if (P.exhaust)
        bx(THREE, g, 0.16, 0.42, 0.34, P.exhaust.x, P.exhaust.y, P.exhaust.z, K.dark);
      for (i = -1; i <= 1; i += 2) {
        bx(THREE, g, 0.18, 0.13, 0.17, P.lampX, i * P.lampY, P.lampZ, K.steel);
        bx(THREE, g, 0.04, 0.11, 0.13, P.lampX + 0.10, i * P.lampY, P.lampZ, K.glass);
      }
      if (P.rearPlate)
        bx(THREE, g, 0.09, P.rearPlate.w, P.rearPlate.h, P.rearPlate.x, 0, P.rearPlate.z, K.dark);
      /* A rear door, and only the infantry carriers get one. When the turret
         is small it is the one honest way to say IFV rather than tank at this
         zoom: Warrior, Marder and Puma all have a full-height power door or
         ramp in the tail and no tank in the roster has anything of the kind. */
      if (P.door) {
        bx(THREE, g, 0.10, P.door.w, P.door.h, P.door.x, 0, P.door.z, K.hull);
        bx(THREE, g, 0.05, 0.10, P.door.h * 0.8, P.door.x - 0.06, P.door.w * 0.28, P.door.z, K.dark);
      }
      /* The Marder 1 of 1971 and nothing else: a REMOTE 7.62 mm MG3 barbette
         on the tail of the troop compartment, firing backwards, aimed by a
         man sitting under it through a periscope. It was deleted in the
         A1A3 and A2 rebuilds, so it dates the vehicle to the decade exactly
         and no other model in this game has a second weapon at the stern. */
      if (P.barbette) {
        czu(THREE, g, 0.26, 0.30, P.barbette.x, 0, P.barbette.z, K.hull, 12);
        bx(THREE, g, 0.30, 0.26, 0.20, P.barbette.x - 0.14, 0, P.barbette.z + 0.20, K.dark);
        cyx(THREE, g, 0.032, 0.48, P.barbette.x - 0.40, 0, P.barbette.z + 0.20, K.steel, 8);
      }

      gear(THREE, g, K, P.gear);

      /* ---- turret ----
         Named "turret" so entities.js slews it. Two defs in this family are
         missing turret:true in the roster - fra_e90_mbt and gbr_e90_ifv -
         and on those the group simply never moves, which is harmless: the
         hull turns to the target and the gun points where the hull points.
         It is a roster fault all the same, and it is reported, not patched
         from inside a model file. */
      var tur = new THREE.Group(); tur.name = "turret";
      tur.position.set(P.turX, P.turY || 0, P.turZ);
      g.add(tur);
      tur.add(new THREE.Mesh(M.loft(THREE, P.turret, 12), K.tur));

      if (P.wedge) wedge(THREE, tur, K, P.wedge);

      /* The mantlet, then the tube. A gun is not one cylinder. The thermal
         sleeve over the middle third, the muzzle reference mirror at the tip
         and - on a RIFLED British gun and on nothing else in this file - the
         fat bore evacuator are what make it read as a gun and not a pole. */
      if (P.mantlet)
        bx(THREE, tur, P.mantlet.len, P.mantlet.w, P.mantlet.h, P.mantlet.x, 0, P.mantlet.z, K.tur);
      var G = P.gun;
      cyx(THREE, tur, G.r, G.len, G.x, 0, G.z, K.steel, 12);
      if (G.sleeve) cyx(THREE, tur, G.r * 1.55, G.len * 0.44, G.x - G.len * 0.16, 0, G.z, K.dark, 12);
      if (G.evac)   cyx(THREE, tur, G.r * 1.95, G.r * 4.6, G.x + G.len * 0.02, 0, G.z, K.steel, 12);
      bx(THREE, tur, 0.10, 0.07, 0.07, G.x + G.len * 0.5 + 0.04, 0, G.z + G.r * 1.3, K.steel);

      /* coaxial machine gun port, just outboard of the mantlet */
      bx(THREE, tur, 0.30, 0.09, 0.09,
         P.mantlet ? P.mantlet.x + 0.30 : G.x - G.len * 0.4, P.coaxY || 0.30, G.z + 0.02, K.dark);

      /* The commander's station. A Puma has NONE - no hatch, no cupola, no
         sight standing up - because nobody is in the turret, and that
         absence is the entire design argument of the vehicle. */
      if (P.cupola) {
        czu(THREE, tur, P.cupola.r, 0.22, P.cupola.x, P.cupola.y, P.cupola.z, K.tur, 14);
        czu(THREE, tur, P.cupola.r * 0.92, 0.05, P.cupola.x, P.cupola.y, P.cupola.z + 0.13, K.hull, 14);
        for (i = 0; i < 6; i++) {
          var a = i / 6 * Math.PI * 2;
          bx(THREE, tur, 0.06, 0.13, 0.09,
             P.cupola.x + Math.cos(a) * P.cupola.r * 0.92,
             P.cupola.y + Math.sin(a) * P.cupola.r * 0.92, P.cupola.z + 0.04, K.glass);
        }
      }
      /* The commander's independent panoramic sight, and WHERE IT SITS dates
         a Leopard 2 for free: on an A4 it is a drum immediately behind the
         gun; on the A5 of 1995 it moved to the back of the roof. */
      if (P.psight) {
        czu(THREE, tur, 0.20, 0.30, P.psight.x, P.psight.y, P.psight.z, K.tur, 12);
        bx(THREE, tur, 0.06, 0.26, 0.18, P.psight.x + 0.19, P.psight.y, P.psight.z + 0.04, K.glass);
      }
      if (P.gsight)
        bx(THREE, tur, 0.10, 0.30, 0.24, P.gsight.x, P.gsight.y, P.gsight.z, K.glass);
      if (P.rws) {
        bx(THREE, tur, 0.44, 0.40, 0.26, P.rws.x, P.rws.y, P.rws.z, K.dark);
        cyx(THREE, tur, 0.035, 0.74, P.rws.x + 0.44, P.rws.y, P.rws.z + 0.06, K.steel, 8);
        bx(THREE, tur, 0.10, 0.20, 0.16, P.rws.x - 0.10, P.rws.y, P.rws.z + 0.20, K.glass);
      }
      /* Roof anti-tank missile: the Marder's MILAN from 1977 and the Puma's
         MELLS (Spike LR2) from 2021. A twin box on the turret flank, high and
         small - it is NOT the Bradley's TOW, which is the point. */
      if (P.atgm) {
        bx(THREE, tur, 0.78, 0.30, 0.34, P.atgm.x, P.atgm.y, P.atgm.z, K.dark);
        bx(THREE, tur, 0.10, 0.32, 0.36, P.atgm.x + 0.42, P.atgm.y, P.atgm.z, K.steel);
      }
      if (P.smoke) smoke(THREE, tur, K, P.smoke);
      /* The bustle rack. On a Challenger it is a deep steel basket running
         the full width of the tail with the crew's world in it; on a Leopard 2
         it is shallower; a Leclerc has none worth drawing because its bustle
         IS the autoloader. */
      if (P.rack) {
        bx(THREE, tur, 0.06, P.rack.w, P.rack.h, P.rack.x - P.rack.len / 2, 0, P.rack.z, K.steel);
        for (i = -1; i <= 1; i += 2)
          bx(THREE, tur, P.rack.len, 0.05, P.rack.h, P.rack.x, i * P.rack.w / 2, P.rack.z, K.steel);
        bx(THREE, tur, P.rack.len, P.rack.w, 0.04, P.rack.x, 0, P.rack.z - P.rack.h / 2, K.steel);
        var duf = new THREE.Mesh(new THREE.SphereGeometry(0.24, 8, 6), K.dark);
        duf.scale.set(1.5, 1.1, 0.85);
        duf.position.set(P.rack.x, P.rack.w * 0.24, P.rack.z + 0.04); tur.add(duf);
        bx(THREE, tur, P.rack.len * 0.5, P.rack.w * 0.34, 0.22,
           P.rack.x - 0.10, -P.rack.w * 0.26, P.rack.z + 0.04, K.dark);
      }
      for (i = -1; i <= 1; i += 2)
        czu(THREE, tur, 0.012, 1.25, P.antX, i * P.antY, P.antZ + 0.62, K.dark, 5);
      /* team flash on the turret flank above the beltline, where a squadron
         marking really goes, so ownership still reads in a melee. */
      for (i = -1; i <= 1; i += 2)
        bx(THREE, tur, 0.66, 0.04, 0.30, P.flashX, i * P.flashY, P.flashZ, K.team);

      g.traverse(function (o) { if (o.isMesh) { o.castShadow = true; o.receiveShadow = true; } });
      return g;
    };
  }

  /* ================================================================ wheeled
     The VBCI, and one builder covers it because it is the only 8x8 in this
     file. It exists because a 32-tonne wheeled IFV drawing on tracks is not
     a wrong detail, it is a wrong class of vehicle. */
  function buildWheeled(P) {
    return function (THREE, M, C) {
      var g = new THREE.Group(), K = kit(THREE, P, C), i, s;

      g.add(new THREE.Mesh(M.loft(THREE, P.hull, 12), K.hull));
      /* The appliqué modules. A VBCI's flanks are bolted titanium and steel
         panels with obvious seams between them, and at this zoom those seams
         are most of what says "armoured" rather than "lorry". */
      for (s = -1; s <= 1; s += 2)
        for (i = 0; i < 5; i++)
          bx(THREE, g, 1.28, 0.06, 0.78, P.panel.x0 + i * 1.34, P.panel.y * s, P.panel.z, K.hull);

      /* Wheels. Four axles a side; the two FRONT pairs steer and sit closer
         together than the rear two, and that grouping is the 8x8 signature -
         it is also what separates it from a six-wheeled AMX-10RC at a glance.
         Left on their default Y axis for the same reason as the road wheels
         above: render3d.js spins a "roadwheel" group about its local Y. */
      for (s = -1; s <= 1; s += 2)
        for (i = 0; i < P.axleX.length; i++) {
          var w = new THREE.Group(); w.name = "roadwheel";
          w.position.set(P.axleX[i], P.axleY * s, P.wheelR);
          w.add(new THREE.Mesh(new THREE.CylinderGeometry(P.wheelR, P.wheelR, P.wheelW, 16), K.rub));
          w.add(new THREE.Mesh(new THREE.CylinderGeometry(
            P.wheelR * 0.52, P.wheelR * 0.52, P.wheelW * 1.04, 10), K.steel));
          for (var b = 0; b < 6; b++) {
            var a = b / 6 * Math.PI * 2;
            var lug = new THREE.Mesh(new THREE.BoxGeometry(
              P.wheelR * 0.20, P.wheelW * 1.12, P.wheelR * 0.12), K.dark);
            lug.position.set(Math.cos(a) * P.wheelR * 0.78, 0, Math.sin(a) * P.wheelR * 0.78);
            lug.rotation.y = -a; w.add(lug);
          }
          g.add(w);
          /* the wheel arch above it, which a tracked vehicle has not got */
          bx(THREE, g, P.wheelR * 2.3, 0.10, 0.12,
             P.axleX[i], (P.axleY - 0.06) * s, P.wheelR * 2.0, K.hull);
        }

      for (i = -1; i <= 1; i += 2) {
        bx(THREE, g, 0.18, 0.14, 0.18, P.lampX, i * P.lampY, P.lampZ, K.steel);
        bx(THREE, g, 0.04, 0.12, 0.14, P.lampX + 0.10, i * P.lampY, P.lampZ, K.glass);
      }
      bx(THREE, g, 0.09, 0.44, 0.22, P.visX, P.visY, P.visZ, K.glass);
      czu(THREE, g, 0.30, 0.07, P.visX - 0.62, P.visY, P.visZ + 0.30, K.hull, 12);
      bx(THREE, g, 0.11, P.ramp.w, P.ramp.h, P.ramp.x, 0, P.ramp.z, K.hull);

      var tur = new THREE.Group(); tur.name = "turret";
      tur.position.set(P.turX, P.turY || 0, P.turZ); g.add(tur);
      tur.add(new THREE.Mesh(M.loft(THREE, P.turret, 12), K.tur));
      bx(THREE, tur, P.mantlet.len, P.mantlet.w, P.mantlet.h, P.mantlet.x, 0, P.mantlet.z, K.tur);
      cyx(THREE, tur, P.gun.r, P.gun.len, P.gun.x, 0, P.gun.z, K.steel, 10);
      cyx(THREE, tur, P.gun.r * 1.5, P.gun.len * 0.22, P.gun.x - P.gun.len * 0.30, 0, P.gun.z, K.dark, 10);
      bx(THREE, tur, 0.30, 0.09, 0.09, P.mantlet.x + 0.28, 0.24, P.gun.z, K.dark);
      czu(THREE, tur, P.cupola.r, 0.20, P.cupola.x, P.cupola.y, P.cupola.z, K.tur, 14);
      bx(THREE, tur, 0.10, 0.28, 0.20, P.cupola.x + 0.26, P.cupola.y, P.cupola.z + 0.02, K.glass);
      if (P.smoke) smoke(THREE, tur, K, P.smoke);
      for (i = -1; i <= 1; i += 2)
        czu(THREE, tur, 0.012, 1.2, P.antX, i * P.antY, P.antZ + 0.60, K.dark, 5);
      for (i = -1; i <= 1; i += 2)
        bx(THREE, tur, 0.60, 0.04, 0.26, P.flashX, i * P.flashY, P.flashZ, K.team);

      g.traverse(function (o) { if (o.isMesh) { o.castShadow = true; o.receiveShadow = true; } });
      return g;
    };
  }

