  /* ---- Challenger: seven ids, three marks -------------------------------
     gbr_e80_mbt and gbr_e90_mbt are both the Challenger 1 of 1983 and the
     roster is right that nothing about the vehicle changed between them -
     but the PAINT changed completely. In 1985 it is a BAOR tank on the North
     German Plain in IRR green and black; in February 1991 it is a DESERT
     SABRE tank in Light Stone, and 221 of them crossed the berm in that
     colour. That is the only difference between the two rows and it is real. */
  UNIT_MODELS["gbr_e80_mbt"]   = challenger(BAOR, 19831, {});
  UNIT_MODELS["gbr_e90_mbt"]   = challenger(SAND, 19912, {});
  /* Challenger 2, 1998: the same hull, the L30A1 in place of the L11A5 and a
     squarer turret front. mbt_b is the e20 fleet standard and gbr_e90_heavy
     is the same tank filling the heavy role. */
  UNIT_MODELS["gbr_e00_mbt"]   = challenger(BAOR, 19983, {});
  UNIT_MODELS["gbr_e90_heavy"] = challenger(BAOR, 19984, {});
  UNIT_MODELS["mbt_b"]         = challenger(BAOR, 20255, {});
  /* Challenger 2 TES, 2009 - the fit the crews called Megatron: Chobham side
     armour, BAR ARMOUR standing off the flanks against RPGs, a remote weapon
     station on the roof and desert paint. The cage is the recognition. */
  UNIT_MODELS["gbr_e00_heavy"] = challenger(SAND, 20096, {
    gear: crGear(0.80, 0.10, { x0: -3.30, x1: 1.60, y: 2.02, z: 0.70 }),
    rws: { x: -0.20, y: 0.72, z: 0.96 },
  });
  /* Challenger 3: 148 Challenger 2 hulls, an entirely NEW turret, Trophy
     active protection, and after sixty years of rifled British tank guns the
     Rheinmetall L55A1 smoothbore. The tube therefore loses its bore
